options.systemMessage:
Identify the language of the user's last message. You MUST respond with ONLY a valid JSON object. Do not add any text, markdown, greetings, or explanations before or after the JSON.

Your entire response must be in the following format:
{
  "language": "the-language-in-lowercase"
}

={{ $json.system_prompt }}

---
Here is some context from the MediaCraft AI knowledge base. Use this to answer the user's question:
CONTEXT:
{{ $json.context }}

parameters.jsCode:
// Get the text from the previous node
const text = $input.item.json.knowledgeBaseText;

// Set our chunking rules
const chunkSize = 1000;
const chunkOverlap = 100;

// Create an array to hold our new chunks
const chunks = [];

// Loop through the text and create chunks
for (let i = 0; i < text.length; i += chunkSize - chunkOverlap) {
  const chunk = text.substring(i, i + chunkSize);
  chunks.push(chunk);
}

// Prepare the final output items
const outputItems = chunks.map(chunk => {
  return {
    json: {
      // We create a "pageContent" field
      // This is the standard name AI nodes look for
      pageContent: chunk
    }
  };
});

// Return all the new items
return outputItems;

// Get all items from the previous node
const items = $items;

// Check if items is an array and has items
if (Array.isArray(items) && items.length > 0) {

  // Create an array of pageContent strings.
  // The correct path is item.json.document.pageContent
  const contentArray = items.map(item => {
    // Check if the path exists before trying to access it
    if (item.json && item.json.document && item.json.document.pageContent) {
      return item.json.document.pageContent;
    }
    return null; // Return null for items with bad structure
  });

  // Filter out any nulls and join the valid text chunks
  const context = contentArray.filter(content => content !== null).join("\n---\n");

  // If we still have an empty context (e.g., bad data), return the fallback
  if (context.length === 0) {
    return [{ json: { context: "No relevant context found." } }];
  }

  // Return a single new item with the combined context
  // Make sure to wrap it in json: {} for the next Merge node
  return [{ 
    json: { 
      context: context 
    } 
  }];
}

// If no items were passed from the previous node, return the fallback
return [{
  json: {
    context: "No relevant context found."
  }
}];
